//! Rust bindings from an API index: `efescript api-export --rust`.
//!
//! The generated file is a Rust module (`mod api;`) for a `#![no_std]` guest crate built for
//! `wasm32-unknown-unknown` with the `efe-guest` crate. It follows the wasm ABI in
//! `docs/e7.4-wasm-design.md`:
//!
//! - one nested Rust module per namespace segment (`engine.world` is `engine::world`), with
//!   `NAMESPACE` and `VERSION` constants, a `raw` module of `unsafe extern "C"` imports
//!   (`#[link(wasm_import_module = "engine.world@1")]`, `#[link_name = "<function>"]`) and a
//!   safe wrapper for each function (`&str`, `&[u8]`, `&Struct`, `bool`; `unsafe fn` when a
//!   parameter is a raw `ptr`);
//! - one `#[repr(C)]` struct per layout at the top level, with `size_of`, `align_of` and
//!   `offset_of!` assertions against the index, and `Entity` for entity values;
//! - one module per event inside its namespace module, with `send`, `count` and `read`;
//! - the index hash in the `efe.api` custom section.
//!
//! Output is a pure function of the index (no dates, sorted order), so it can be checked in.
//! Names that Rust cannot spell are an error, never broken code.

use efevm::api::{ApiIndex, ApiType, EventDesc, HostFn, Prim, StructDesc};
use std::collections::BTreeSet;
use std::fmt::Write;

pub use crate::bindmodel::BindError as RustgenError;
use crate::bindmodel::{build_tree, err, layout, single_result, Node};

/// Strict, edition 2018+ and reserved keywords: written as `r#name`.
const KEYWORDS: &[&str] = &[
    "abstract", "as", "async", "await", "become", "box", "break", "const", "continue", "do", "dyn", "else", "enum", "extern",
    "false", "final", "fn", "for", "gen", "if", "impl", "in", "let", "loop", "macro", "match", "mod", "move", "mut", "override",
    "priv", "pub", "ref", "return", "static", "struct", "trait", "true", "try", "type", "typeof", "unsafe", "unsized", "use",
    "virtual", "where", "while", "yield",
];
/// Keywords that cannot be raw identifiers.
const NO_RAW: &[&str] = &["crate", "self", "Self", "super"];
/// Primitive type names: a struct of that name would break the generated code.
const PRIMS: &[&str] = &[
    "bool", "char", "str", "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16", "i32", "i64", "i128", "isize", "f32", "f64",
];

/// The Rust spelling of an index name, `r#`-escaped when it is a keyword.
fn ident(name: &str, what: &str) -> Result<String, RustgenError> {
    if name == "_" || NO_RAW.contains(&name) {
        return err(format!("{what} `{name}` cannot be used as a Rust name (not even as `r#{name}`); rename it in the index"));
    }
    if KEYWORDS.contains(&name) { Ok(format!("r#{name}")) } else { Ok(name.to_string()) }
}

fn type_ident(name: &str, what: &str) -> Result<String, RustgenError> {
    if name.starts_with("mod:") {
        return err(format!("{what} `{name}` is a mod-defined component and has no Rust name"));
    }
    if PRIMS.contains(&name) {
        return err(format!("{what} `{name}` is a Rust primitive type name; rename it in the index"));
    }
    ident(name, what)
}

fn supers(n: usize) -> String {
    "super::".repeat(n)
}

/// `///` lines for an index doc: leading blanks trimmed (so a doc never becomes an indented
/// code block) and code fences escaped (so it never becomes a doctest).
fn doc(out: &mut String, indent: &str, text: &str) {
    for line in text.lines() {
        let line = line.trim().replace("```", "\\`\\`\\`");
        let _ = writeln!(out, "{}", format!("{indent}/// {line}").trim_end());
    }
}

/// Generates the Rust bindings of `ix`. See the module docs for what they contain.
pub fn generate(ix: &ApiIndex) -> Result<String, RustgenError> {
    let mut g = Gen { ix, out: String::new() };
    g.run()?;
    Ok(g.out)
}

struct Gen<'a> {
    ix: &'a ApiIndex,
    out: String,
}

impl<'a> Gen<'a> {
    fn run(&mut self) -> Result<(), RustgenError> {
        let ix = self.ix;
        let root = build_tree(ix)?;
        self.check_names(&root)?;

        let hash = ix.hash();
        let game = if ix.game.is_empty() { "(unnamed)" } else { ix.game.as_str() };
        let o = &mut self.out;
        let _ = writeln!(o, "// @generated by `efescript api-export --rust`. Do not edit: regenerate it instead.");
        let _ = writeln!(o, "// API index `{game}`, hash fnv1a64:{hash:016x}.");
        let _ = writeln!(o, "//! Rust bindings of the efescript API index `{game}` (hash `fnv1a64:{hash:016x}`).");
        let _ = writeln!(o, "//!");
        let _ = writeln!(o, "//! Use this file as a module (`mod api;`) of a `#![no_std]` crate built for");
        let _ = writeln!(o, "//! `wasm32-unknown-unknown` that depends on `efe-guest`. The wasm ABI is described in");
        let _ = writeln!(o, "//! `crates/efescript/docs/e7.4-wasm-design.md`.");
        let _ = writeln!(o, "#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code, unused_unsafe, unused_imports)]");
        let _ = writeln!(o);
        let _ = writeln!(o, "pub use ::efe_guest::Entity;");
        let _ = writeln!(o);
        let _ = writeln!(o, "/// The name of the index these bindings were generated from.");
        let _ = writeln!(o, "pub const API_GAME: &str = {game:?};");
        let _ = writeln!(o, "/// The FNV-1a hash of the index (also the `efe.api` custom section).");
        let _ = writeln!(o, "pub const API_HASH: u64 = 0x{hash:016x};");
        let _ = writeln!(o);
        let _ = writeln!(o, "/// The `efe.api` custom section: the index hash, 8 bytes little-endian (design doc, section 3).");
        let _ = writeln!(o, "#[cfg_attr(target_arch = \"wasm32\", unsafe(link_section = \"efe.api\"))]");
        let _ = writeln!(o, "#[used]");
        let _ = writeln!(o, "static EFE_API: [u8; 8] = API_HASH.to_le_bytes();");

        for t in &ix.types {
            if t.name.starts_with("mod:") {
                let _ = writeln!(self.out, "\n// Skipped: `{}` is a mod-defined component, not usable in signatures.", t.name);
                continue;
            }
            self.strukt(t)?;
        }
        self.module_body(&root, 0, true)?;
        Ok(())
    }

    /// Name collisions inside every generated module, reported by index name.
    fn check_names(&self, root: &Node<'a>) -> Result<(), RustgenError> {
        let mut top: BTreeSet<&str> = BTreeSet::new();
        top.insert("Entity");
        for t in &self.ix.types {
            if t.name.starts_with("mod:") {
                continue;
            }
            type_ident(&t.name, "struct")?;
            if !top.insert(&t.name) {
                return err(format!("struct `{}` collides with a generated item at the top level (`Entity` is reserved)", t.name));
            }
        }
        for c in root.children.keys() {
            ident(c, "namespace")?;
            if !top.insert(c) {
                return err(format!("namespace `{c}` collides with a struct or `Entity` at the top level"));
            }
        }
        fn walk(n: &Node, path: &str) -> Result<(), RustgenError> {
            let mut types: BTreeSet<&str> = BTreeSet::new();
            if !n.funcs.is_empty() {
                types.insert("raw");
            }
            let mut values: BTreeSet<&str> = BTreeSet::new();
            if n.info.is_some() {
                values.extend(["NAMESPACE", "VERSION"]);
            }
            for c in n.children.keys() {
                ident(c, "namespace")?;
                if !types.insert(c) {
                    return err(format!("namespace `{path}.{c}` collides with a generated module of `{path}`"));
                }
            }
            for e in &n.events {
                ident(&e.name, "event")?;
                if !types.insert(&e.name) {
                    return err(format!("event `{path}.{}` collides with another module of `{path}` (`raw` is reserved)", e.name));
                }
            }
            for f in &n.funcs {
                ident(&f.name, "function")?;
                if !values.insert(&f.name) {
                    return err(format!("function `{path}.{}` collides with a generated constant", f.name));
                }
            }
            for (c, ch) in &n.children {
                walk(ch, &format!("{path}.{c}"))?;
            }
            Ok(())
        }
        for (c, ch) in &root.children {
            walk(ch, c)?;
        }
        Ok(())
    }

    fn strukt(&mut self, t: &StructDesc) -> Result<(), RustgenError> {
        let name = type_ident(&t.name, "struct")?;
        let lay = layout(t)?;
        let mut body = Vec::new(); // (doc, name, type, hidden)
        for f in &lay.fields {
            match f.ty {
                None => body.push((String::new(), f.name.clone(), format!("[u8; {}]", f.count), true)),
                Some(p) => {
                    let ty = prim_rust(p);
                    let ty = if f.count > 1 { format!("[{ty}; {}]", f.count) } else { ty };
                    body.push((f.doc.clone(), ident(&f.name, &format!("struct `{}` field", t.name))?, ty, false));
                }
            }
        }
        let repr = if lay.natural_align < t.align { format!("#[repr(C, align({}))]", t.align) } else { "#[repr(C)]".to_string() };

        let o = &mut self.out;
        let _ = writeln!(o);
        if t.doc.is_empty() {
            let _ = writeln!(o, "/// Layout `{}` of the API index.", t.name);
        } else {
            doc(o, "", &t.doc);
        }
        let _ = writeln!(o, "///");
        let comp = t.component.map(|c| format!(", component id {c}")).unwrap_or_default();
        let _ = writeln!(o, "/// Size {}, alignment {}, owner `{}`{comp}.", t.size, t.align, t.owner);
        let _ = writeln!(o, "{repr}");
        let _ = writeln!(o, "#[derive(Clone, Copy, Debug, PartialEq)]");
        let _ = writeln!(o, "pub struct {name} {{");
        for (d, n, ty, hidden) in &body {
            if *hidden {
                let _ = writeln!(o, "    #[doc(hidden)]");
            } else {
                doc(o, "    ", d);
            }
            let _ = writeln!(o, "    pub {n}: {ty},");
        }
        let _ = writeln!(o, "}}");
        let _ = writeln!(o, "impl {name} {{");
        let _ = writeln!(o, "    /// Size in bytes, as in the index.");
        let _ = writeln!(o, "    pub const SIZE: usize = {};", t.size);
        if let Some(c) = t.component {
            let _ = writeln!(o, "    /// The component id scripts pass to `engine.world.*`.");
            let _ = writeln!(o, "    pub const COMPONENT: u32 = {c};");
        }
        let _ = writeln!(o, "    /// All bytes zero (every field is plain data, so this is a valid value).");
        let _ = writeln!(o, "    pub const fn zeroed() -> Self {{");
        let _ = writeln!(o, "        unsafe {{ ::core::mem::zeroed() }}");
        let _ = writeln!(o, "    }}");
        let _ = writeln!(o, "}}");
        let _ = writeln!(o, "impl ::core::default::Default for {name} {{");
        let _ = writeln!(o, "    fn default() -> Self {{");
        let _ = writeln!(o, "        Self::zeroed()");
        let _ = writeln!(o, "    }}");
        let _ = writeln!(o, "}}");
        let _ = writeln!(o, "impl ::efe_guest::GuestStruct for {name} {{");
        let _ = writeln!(o, "    const NAME: &'static str = {:?};", t.name);
        let _ = writeln!(o, "}}");
        let _ = writeln!(o, "const _: () = {{");
        let _ = writeln!(o, "    assert!(::core::mem::size_of::<{name}>() == {});", t.size);
        let _ = writeln!(o, "    assert!(::core::mem::align_of::<{name}>() == {});", t.align);
        for f in lay.fields.iter().filter(|f| !f.is_pad()) {
            let n = ident(&f.name, "field")?;
            let _ = writeln!(o, "    assert!(::core::mem::offset_of!({name}, {n}) == {});", f.offset);
        }
        let _ = writeln!(o, "}};");
        Ok(())
    }

    fn module_body(&mut self, n: &Node<'a>, depth: usize, is_root: bool) -> Result<(), RustgenError> {
        let ind = "    ".repeat(depth);
        if !is_root {
            if !n.funcs.is_empty() {
                self.raw_module(n, depth, &ind)?;
            }
            if let Some(i) = n.info {
                let _ = writeln!(self.out, "{ind}/// The namespace name.");
                let _ = writeln!(self.out, "{ind}pub const NAMESPACE: &str = {:?};", i.name);
                let _ = writeln!(self.out, "{ind}/// The namespace version the bindings were generated against.");
                let _ = writeln!(self.out, "{ind}pub const VERSION: u32 = {};", i.version);
            }
            for f in &n.funcs {
                self.wrapper(f, depth, &ind)?;
            }
            for e in &n.events {
                self.event(e, n, depth, &ind)?;
            }
        }
        for (name, child) in &n.children {
            let id = ident(name, "namespace")?;
            let o = &mut self.out;
            let _ = writeln!(o);
            match child.info {
                Some(i) if !i.doc.is_empty() => doc(o, &ind, &i.doc),
                _ => {
                    let full = child.info.map(|i| i.name.clone()).unwrap_or_else(|| name.clone());
                    let _ = writeln!(o, "{ind}/// Namespace `{full}`.");
                }
            }
            let _ = writeln!(o, "{ind}pub mod {id} {{");
            self.module_body(child, depth + 1, false)?;
            let _ = writeln!(self.out, "{ind}}}");
        }
        Ok(())
    }

    /// Wasm-level parameters of a function as `(rust type, name)` pairs, one per wasm value.
    fn raw_params(f: &HostFn, up: usize) -> Result<Vec<(String, String)>, RustgenError> {
        let q = f.qualified();
        let mut out: Vec<(String, String)> = Vec::new();
        for p in &f.params {
            let base = ident(&p.name, &format!("{q}: parameter"))?;
            match &p.ty {
                ApiType::Str | ApiType::Bytes => {
                    let b = p.name.as_str();
                    out.push(("*const u8".into(), format!("{b}_ptr")));
                    out.push(("usize".into(), format!("{b}_len")));
                }
                ApiType::Struct(s) => out.push((format!("*const {}{}", supers(up), type_ident(s, &format!("{q}: struct"))?), base)),
                ApiType::Bool => out.push(("i32".into(), base)),
                t => out.push((scalar_rust(t).into(), base)),
            }
        }
        let mut seen = BTreeSet::new();
        for (_, n) in &out {
            if !seen.insert(n.trim_start_matches("r#")) {
                return err(format!("{q}: parameter names collide after lowering (`{n}`)"));
            }
        }
        Ok(out)
    }

    fn result_types(f: &HostFn) -> Result<Option<(&'static str, &'static str)>, RustgenError> {
        Ok(single_result(f)?.map(|t| match t {
            ApiType::Bool => ("i32", "bool"),
            t => (scalar_rust(t), scalar_rust(t)),
        }))
    }

    fn raw_module(&mut self, n: &Node<'a>, depth: usize, ind: &str) -> Result<(), RustgenError> {
        let version = n.info.map(|i| i.version).ok_or_else(|| RustgenError(format!("namespace of `{}` is not listed", n.funcs[0].qualified())))?;
        let ns = &n.funcs[0].namespace;
        let mut s = String::new();
        let _ = writeln!(s, "{ind}/// The raw imports of this namespace: wasm import module `{ns}@{version}`.");
        let _ = writeln!(s, "{ind}pub mod raw {{");
        let _ = writeln!(s, "{ind}    #[link(wasm_import_module = \"{ns}@{version}\")]");
        let _ = writeln!(s, "{ind}    unsafe extern \"C\" {{");
        for f in &n.funcs {
            let params = Self::raw_params(f, depth + 1)?;
            let list = params.iter().map(|(t, n)| format!("{n}: {t}")).collect::<Vec<_>>().join(", ");
            let ret = Self::result_types(f)?.map(|(r, _)| format!(" -> {r}")).unwrap_or_default();
            let _ = writeln!(s, "{ind}        #[link_name = {:?}]", f.name);
            let _ = writeln!(s, "{ind}        pub fn {}({list}){ret};", ident(&f.name, "function")?);
        }
        let _ = writeln!(s, "{ind}    }}");
        let _ = writeln!(s, "{ind}}}");
        self.out.push_str(&s);
        Ok(())
    }

    fn wrapper(&mut self, f: &HostFn, depth: usize, ind: &str) -> Result<(), RustgenError> {
        let q = f.qualified();
        let name = ident(&f.name, "function")?;
        let mut params = Vec::new();
        let mut args = Vec::new();
        let mut is_unsafe = false;
        for p in &f.params {
            let pn = ident(&p.name, &format!("{q}: parameter"))?;
            let (ty, call) = match &p.ty {
                ApiType::I32 | ApiType::I64 | ApiType::F32 | ApiType::F64 | ApiType::Entity => (scalar_rust(&p.ty).to_string(), pn.clone()),
                ApiType::Bool => ("bool".to_string(), format!("{pn} as i32")),
                ApiType::Ptr => {
                    is_unsafe = true;
                    ("*mut u8".to_string(), pn.clone())
                }
                ApiType::Str => ("&str".to_string(), format!("{pn}.as_ptr(), {pn}.len()")),
                ApiType::Bytes => ("&[u8]".to_string(), format!("{pn}.as_ptr(), {pn}.len()")),
                ApiType::Struct(s) => (format!("&{}{}", supers(depth), type_ident(s, &format!("{q}: struct"))?), pn.clone()),
            };
            params.push(format!("{pn}: {ty}"));
            args.push(call);
        }
        let (ret_decl, post) = match (Self::result_types(f)?, f.results.first().map(|r| &r.ty)) {
            (None, _) => (String::new(), ""),
            (Some((_, rust)), Some(ApiType::Bool)) => (format!(" -> {rust}"), " != 0"),
            (Some((_, rust)), _) => (format!(" -> {rust}"), ""),
        };
        let o = &mut self.out;
        let _ = writeln!(o);
        doc(o, ind, &f.doc);
        let _ = writeln!(o, "{ind}///");
        let _ = writeln!(o, "{ind}/// Index signature: `{}`.", f.signature_text());
        if is_unsafe {
            let _ = writeln!(o, "{ind}///");
            let _ = writeln!(o, "{ind}/// # Safety");
            let _ = writeln!(o, "{ind}/// A `ptr` argument is a raw address in this module's memory that the host reads or writes.");
        }
        let kw = if is_unsafe { "pub unsafe fn" } else { "pub fn" };
        let call = format!("raw::{name}({})", args.join(", "));
        let _ = writeln!(o, "{ind}{kw} {name}({}){ret_decl} {{", params.join(", "));
        let _ = writeln!(o, "{ind}    unsafe {{ {call}{post} }}");
        let _ = writeln!(o, "{ind}}}");
        Ok(())
    }

    fn event(&mut self, e: &EventDesc, n: &Node<'a>, depth: usize, ind: &str) -> Result<(), RustgenError> {
        let q = e.qualified();
        let name = ident(&e.name, "event")?;
        let version = n.info.map(|i| i.version).ok_or_else(|| RustgenError(format!("namespace of event `{q}` is not listed")))?;
        let payload = match &e.payload {
            Some(p) => Some(type_ident(p, &format!("event `{q}` payload struct"))?),
            None => None,
        };
        let o = &mut self.out;
        let _ = writeln!(o);
        doc(o, ind, &e.doc);
        let _ = writeln!(o, "{ind}///");
        let _ = writeln!(o, "{ind}/// Event `{q}`; wasm imports `{}@{version}` / `{}.send`, `.count`{}.", e.namespace, e.name, if payload.is_some() { ", `.read`" } else { "" });
        let _ = writeln!(o, "{ind}pub mod {name} {{");
        let i2 = format!("{ind}    ");
        let _ = writeln!(o, "{i2}/// The qualified event name.");
        let _ = writeln!(o, "{i2}pub const NAME: &str = {q:?};");
        if let Some(p) = &payload {
            let _ = writeln!(o, "{i2}/// The payload struct.");
            let _ = writeln!(o, "{i2}pub type Payload = {}{p};", supers(depth + 1));
        }
        let _ = writeln!(o, "{i2}mod raw {{");
        let _ = writeln!(o, "{i2}    #[link(wasm_import_module = \"{}@{version}\")]", e.namespace);
        let _ = writeln!(o, "{i2}    unsafe extern \"C\" {{");
        let sup = supers(depth + 2);
        match &payload {
            Some(p) => {
                let _ = writeln!(o, "{i2}        #[link_name = \"{}.send\"]\n{i2}        pub fn send(payload: *const {sup}{p});", e.name);
            }
            None => {
                let _ = writeln!(o, "{i2}        #[link_name = \"{}.send\"]\n{i2}        pub fn send();", e.name);
            }
        }
        let _ = writeln!(o, "{i2}        #[link_name = \"{}.count\"]\n{i2}        pub fn count() -> i32;", e.name);
        if let Some(p) = &payload {
            let _ = writeln!(o, "{i2}        #[link_name = \"{}.read\"]\n{i2}        pub fn read(index: u32, out: *mut {sup}{p}) -> i32;", e.name);
        }
        let _ = writeln!(o, "{i2}    }}");
        let _ = writeln!(o, "{i2}}}");
        if payload.is_some() {
            let _ = writeln!(o, "{i2}/// Queues the event; readers see it during the next frame.");
            let _ = writeln!(o, "{i2}pub fn send(payload: &Payload) {{\n{i2}    unsafe {{ raw::send(payload) }}\n{i2}}}");
        } else {
            let _ = writeln!(o, "{i2}/// Queues the event; readers see it during the next frame.");
            let _ = writeln!(o, "{i2}pub fn send() {{\n{i2}    unsafe {{ raw::send() }}\n{i2}}}");
        }
        let _ = writeln!(o, "{i2}/// The number of these events readable this frame.");
        let _ = writeln!(o, "{i2}pub fn count() -> u32 {{\n{i2}    unsafe {{ raw::count() as u32 }}\n{i2}}}");
        if payload.is_some() {
            let _ = writeln!(o, "{i2}/// The payload of the `index`-th (0-based) event of this frame.");
            let _ = writeln!(o, "{i2}pub fn read(index: u32) -> ::core::option::Option<Payload> {{");
            let _ = writeln!(o, "{i2}    let mut out = Payload::zeroed();");
            let _ = writeln!(o, "{i2}    if unsafe {{ raw::read(index, &mut out) }} == 0 {{ ::core::option::Option::Some(out) }} else {{ ::core::option::Option::None }}");
            let _ = writeln!(o, "{i2}}}");
            let _ = writeln!(o, "{i2}/// All payloads of this frame, in order.");
            let _ = writeln!(o, "{i2}pub fn iter() -> impl ::core::iter::Iterator<Item = Payload> {{\n{i2}    (0..count()).filter_map(read)\n{i2}}}");
        }
        let _ = writeln!(o, "{ind}}}");
        Ok(())
    }
}

fn scalar_rust(t: &ApiType) -> &'static str {
    match t {
        ApiType::I32 | ApiType::Bool => "i32",
        ApiType::I64 => "i64",
        ApiType::F32 => "f32",
        ApiType::F64 => "f64",
        ApiType::Entity => "::efe_guest::Entity",
        ApiType::Ptr => "*mut u8",
        _ => unreachable!("not a scalar"),
    }
}

fn prim_rust(p: Prim) -> String {
    match p {
        Prim::Entity => "::efe_guest::Entity".into(),
        p => p.name().into(),
    }
}
